window.WARNO_UNIT_ICONS.kindType = {"tank":"Armor","armor":"Armor","infantry":"Infantry","inf":"Infantry","atgm":"AT","at":"AT","aa":"AA","arty":"howitzer","art":"howitzer","helo":"hel","hel":"hel","air":"Support_air","recon":"reco","rec":"reco","log":"supply","supply":"supply","cmd":"CMD_veh","rally":"supply","defend":"Infantry","enemy":"Armor","advance":"Infantry","flank":"Armor","retreat":"supply","support":"appui","chokepoints":"default"};
window.WARNO_UNIT_ICONS.typeAliases = {"Armor_heavy":"Armor","RECO_inf_sf":"RECO_inf","Infantry_sf":"sf","CMD_inf_sf":"CMD_inf","ATGun":"AT","FireSupport":"appui","SEAD_hel":"SEAD_air"};
window.WARNO_UNIT_ICONS.resolveTypeIcon = function(side, unit, kind) {
  const S = String(side || "NATO").toUpperCase().includes("PACT") ? "PACT" : "NATO";
  function stemFromUnit(u) {
    if (!u) return null;
    let d = u.descriptor || null;
    if (!d && u.id != null && window.WarnoLib && window.WarnoLib.UNITS) {
      const full = window.WarnoLib.UNITS[u.id] || window.WarnoLib.UNITS[String(u.id)];
      if (full) { d = full.descriptor; u = full; }
    }
    if (d) {
      const m = String(d).match(/Descriptor_Unit_(.+)$/);
      if (m) return m[1];
    }
    return null;
  }
  // Prefer marker role (kind) so tactical map AT/armor/recon spots get the right pictogram;
  // fall back to the concrete unit MenuIcon type when kind is unknown.
  let typeStem = null;
  if (kind && this.kindType[kind]) typeStem = this.kindType[kind];
  const unitStem = stemFromUnit(unit);
  if (!typeStem && unitStem && this.unitTypeByStem[unitStem]) typeStem = this.unitTypeByStem[unitStem];
  if (!typeStem && unit && unit.category && this.kindType[unit.category]) typeStem = this.kindType[unit.category];
  if (!typeStem && unitStem && this.unitTypeByStem[unitStem]) typeStem = this.unitTypeByStem[unitStem];
  if (!typeStem) typeStem = "default";
  if (this.typeAliases[typeStem]) typeStem = this.typeAliases[typeStem];
  const path = this.typeDir + S + "/" + typeStem + ".png";
  return path;
};
